alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create function public.is_friend(target uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.friendships
    where ((requester_id = auth.uid() and addressee_id = target)
           or (requester_id = target and addressee_id = auth.uid()))
      and status = 'accepted'
  );
$$;

revoke all on function public.is_friend(uuid) from public;
grant execute on function public.is_friend(uuid) to anon, authenticated, service_role;

create policy "posts_select_visible_to_audience"
on public.posts
for select
to anon, authenticated
using (
  audience = 'public'
  or author_id = auth.uid()
  or public.is_friend(author_id)
);

create policy "posts_insert_own_only"
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy "posts_update_own_only"
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "posts_delete_own_only"
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy "friendships_select_involved"
on public.friendships
for select
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy "friendships_insert_request_only"
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
);

create policy "friendships_update_addressee_accept_pending"
on public.friendships
for update
to authenticated
using (
  addressee_id = auth.uid()
  and status = 'pending'
)
with check (
  addressee_id = auth.uid()
  and status = 'accepted'
);

create policy "friendships_delete_involved"
on public.friendships
for delete
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

revoke all on table public.friendships from anon;
revoke all on table public.posts from anon;
grant select on table public.posts to anon;
grant select, insert, update, delete on table public.posts to authenticated;
grant select, insert, update, delete on table public.friendships to authenticated;
