security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.org_members
    where org_id = p_org_id
      and user_id = auth.uid()
      and role = 'admin'
  );
$$;

create function public.requires_sso_for_org(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.orgs
    where id = p_org_id
      and require_sso = true
  );
$$;

create function public.has_sso_session()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from jsonb_array_elements_text(auth.jwt() -> 'amr')
    as amr_entry
    where amr_entry::jsonb ->> 'method' = 'sso/saml'
  );
$$;

