alter table public.org_members enable row level security;
alter table public.org_documents enable row level security;

create policy orgs_select_member
  on public.orgs
  for select
  to authenticated
  using (
    public.is_org_member(id)
    and (not public.requires_sso_for_org(id) or public.has_sso_session())
  );

create policy org_members_select_member
  on public.org_members
  for select
  to authenticated
  using (
    public.is_org_member(org_id)
    and (not public.requires_sso_for_org(org_id) or public.has_sso_session())
  );

create policy org_documents_select_member
  on public.org_documents
  for select
  to authenticated
  using (
    public.is_org_member(org_id)
    and (not public.requires_sso_for_org(org_id) or public.has_sso_session())
  );

create policy org_documents_insert_admin
  on public.org_documents
  for insert
  to authenticated
  with check (
    public.is_org_admin(org_id)
    and public.has_sso_session()
  );

create policy org_documents_update_admin
  on public.org_documents
  for update
  to authenticated
  using (
    public.is_org_admin(org_id)
    and public.has_sso_session()
  )
  with check (
    public.is_org_admin(org_id)
    and public.has_sso_session()
  );

create policy org_documents_delete_admin
  on public.org_documents
  for delete
