    select 1 from public.requests
    where id = p_request_id
      and public.can_view_unit(requests.unit_id)
  );
$$;

create function public.enforce_requests_immutable()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid() then
      raise exception 'created_by must match current user';
    end if;
    if new.status <> 'open' then
      raise exception 'new requests must be open';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.id is distinct from new.id
       or old.unit_id is distinct from new.unit_id
       or old.created_by is distinct from new.created_by
       or old.description is distinct from new.description then
      raise exception 'only status can be changed on a request';
    end if;

    if not public.is_building_staff((select u.building_id from public.units u where u.id = old.unit_id)) then
      raise exception 'only building staff can update request status';
    end if;

    return new;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'requests cannot be deleted';
  end if;

  return new;
end;
$$;

