for update
to authenticated
using (public.is_building_staff((select u.building_id from public.units u where u.id = unit_id)))
with check (public.is_building_staff((select u.building_id from public.units u where u.id = unit_id)));

create policy request_photos_select_visible
on public.request_photos
for select
to authenticated
using (public.can_view_unit((select u.id from public.units u where u.id = (select r.unit_id from public.requests r where r.id = request_photos.request_id))));

