    select 1 from public.supervisors
    where user_id = auth.uid()
  );
$$;

create function public.mask_email(email text)
returns text
language sql
immutable
as $$
  select left(email, 1) || '***' || substring(email from '@');
$$;

create function public.mask_phone(phone text)
returns text
language sql
immutable
as $$
  select '******' || right(phone, 4);
$$;

