create function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_seller uuid;
  v_ends_at timestamptz;
  v_current_highest_bid numeric;
  v_min_increment numeric;
  v_bidder uuid := auth.uid();
begin
  if v_bidder is null then
    raise exception 'not authenticated';
  end if;

  select a.seller_id, a.ends_at, a.highest_bid, a.min_increment
    into v_seller, v_ends_at, v_current_highest_bid, v_min_increment
  from public.auctions a
  where a.id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_seller = v_bidder then
    raise exception 'cannot bid on own auction';
  end if;

  if v_current_highest_bid is null then
    if p_amount <= v_seller.starting_price then
      raise exception 'bid must be above starting price';
    else
      v_current_highest_bid := v_seller.starting_price;
    end if;
  else
    if p_amount <= (v_current_highest_bid + v_seller.min_increment) then
      raise exception 'bid must be above current highest bid plus minimum increment';
    else
      v_current_highest_bid := p_amount;
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_bidder, p_amount);

  update public.auctions
  set highest_bid = v_current_highest_bid,
      highest_bidder = v_bidder
  where id = p_auction_id;

  return p_amount;
end;
$$;

