as $$
  select exists (
    select 1 from public.classes
    where id = p_class_id
      and instructor_id = auth.uid()
  );
$$;

create function public.can_join_class(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.classes
    where id = p_class_id
      and (select count(*) from public.class_spots cs where cs.class_id = classes.id and cs.status = 'enrolled') < classes.capacity
  );
$$;

create function public.enforce_class_spots_integrity()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id is distinct from auth.uid() then
      raise exception 'only self can join classes';
    end if;

    if new.status = 'enrolled' then
      if not public.can_join_class(new.class_id) then
        raise exception 'class is full';
      end if;
    elsif new.status = 'waitlisted' then
      if not public.can_join_class(new.class_id) then
        raise exception 'class is full';
      end if;
    else
      raise exception 'invalid status';
    end if;
  elsif tg_op = 'UPDATE' then
    if old.class_id is distinct from new.class_id or old.user_id is distinct from new.user_id then
      raise exception 'class spots cannot be moved';
    end if;

    if old.status = 'enrolled' then
      raise exception 'enrolled spots cannot be changed';
    end if;

    if new.status = 'enrolled' then
      if not public.can_join_class(old.class_id) then
        raise exception 'no room to enroll';
      end if;
    elsif new.status = 'waitlisted' then
      if old.status = 'waitlisted' then
        raise exception 'waitlisted spots cannot be changed';
      end if;
    else
      raise exception 'invalid status';
    end if;
  end if;

  return new;
end;
$$;

