create function public.is_class_instructor(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.classes
    where id = p_class_id
      and instructor_id = auth.uid()
  );
$$;

create function public.can_join_class(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.classes
    where id = p_class_id
      and (select count(*) from public.class_spots s where s.class_id = classes.id and s.status = 'enrolled') < capacity
  );
$$;

create function public.enforce_class_spots_constraints()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id is distinct from auth.uid() then
      raise exception 'can only join classes as yourself';
    end if;

    if new.status = 'enrolled' then
      if not exists (
        select 1 from public.classes
        where id = new.class_id
          and (select count(*) from public.class_spots s where s.class_id = classes.id and s.status = 'enrolled') < capacity
      ) then
        raise exception 'class is full';
      end if;
    elsif new.status = 'waitlisted' then
      if exists (
        select 1 from public.class_spots
        where class_id = new.class_id
          and user_id = new.user_id
          and status = 'enrolled'
      ) then
        raise exception 'already enrolled in this class';
      end if;
    else
      raise exception 'invalid spot status';
    end if;

    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.class_id is distinct from new.class_id or old.user_id is distinct from new.user_id then
      raise exception 'class spots cannot be moved';
    end if;

    if old.status = 'enrolled' then
      raise exception 'enrolled spots cannot be changed';
    end if;

    if new.status = 'enrolled' then
      if not public.is_class_instructor(old.class_id) then
        if not exists (
          select 1 from public.classes
          where id = old.class_id
            and (select count(*) from public.class_spots s where s.class_id = classes.id and s.status = 'enrolled') < capacity
        ) then
          raise exception 'class is full';
        end if;
      end if;
    elsif new.status = 'waitlisted' then
      if not public.is_class_instructor(old.class_id) then
        raise exception 'waitlisted spots cannot be downgraded';
      end if;
    else
      raise exception 'invalid spot status';
    end if;

    return new;
  end if;

  return new;
end;
$$;

create trigger class_spots_enforce_constraints
before insert or update on public.class_spots
for each row
execute function public.enforce_class_spots_constraints();

